<span class="line"><span style="color:#24292E;">    out </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> run_agent_stub(</span><span style="color:#032F62;">&quot;查 Python&quot;</span><span style="color:#24292E;">, tools, FakeLLM(replies))</span></span>
